import{_ as e,o as t,c as o,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const i=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Commands.md","filePath":"manual-zh/Commands.md","lastUpdated":1785684581000}'),d={name:"manual-zh/Commands.md"};function r(s,a,_,c,m,p){return t(),o("div",null,[...a[0]||(a[0]=[n('<h3 id="_6-2-由词法符号组成命令" tabindex="-1">6.2 由词法符号组成命令 <a class="header-anchor" href="#_6-2-由词法符号组成命令" aria-label="Permalink to &quot;6.2 由词法符号组成命令&quot;">​</a></h3><p>大多数 PSPP 命令共享一种通用结构。命令以命令名开头，例如 <code>FREQUENCIES</code>、<code>DATA LIST</code> 或 <code>N OF CASES</code>。命令名可缩写为其第一个词，命令名中的每个词可缩写为其前三个或更多个字符，只要这些缩写无歧义。</p><p>命令名后面可跟一个或多个_子命令_。每个子命令以子命令名开头，子命令名可缩写为其前三个字母。某些子命令接受一系列一个或多个说明，这些说明跟在子命令名之后，可选择以等号（‘=’）与之分隔。各个说明之间可用逗号或空格分隔。每个子命令必须与下一个（若有）以正斜杠（‘/’）分隔。</p><p>有多种方式可以标记命令的结束。最常见的方式是以上一节所述（参见 <a href="./Tokens">词法符号</a>）的句点（‘.’）结束命令的最后一行。空行，或仅由空白或注释组成的行，也会结束命令。</p>',4)])])}const h=e(d,[["render",r]]);export{i as __pageData,h as default};
